import { VStack, Heading, Textб  } from "@chakra-ui/react";
import { useEffect, useState } from "react";
import { getCards } from "../endpoints/api";

const MainPage = () => {
  const [cards, setCards] = useState([]);

  useEffect(() => {
    const fetchCards = async () => {
      const cardsData = await getCards();
      console.log("Cards data:", cardsData); // Отладка
      setCards(cardsData || []); // Если cardsData не массив, используем пустой массив
    };
    fetchCards();
  }, []);

  return (
    <VStack>
      <Heading> Welcome back user!</Heading>
      <VStack>
        {Array.isArray(cards) &&
          cards.map((card) => {
            return (
              <Text key={card.id}>
                {card.id} {card.first_name} {card.address}{" "}
                {card.doctor?.first_name} {card.doctor?.surname}{" "}
                {card.doctor?.last_name}
              </Text>
            );
          })}
      </VStack>
    </VStack>
  );
};

export default MainPage;
